#!/data/data/com.termux/files/usr/bin/bash
# ELAINA Optimasi - RAM Auto Interval
# Source-project extractor for Termux / GitHub Actions.
# This script extracts source files; it does not itself compile or install an APK.
set -eu

PROJECT_DIR="${1:-ELAINA_Optimasi_RAM_AutoInterval}"
if [ -e "$PROJECT_DIR" ]; then
  echo "[ELAINA] Folder '$PROJECT_DIR' sudah ada; tidak menimpa file lama."
  echo "Jalankan dengan nama folder lain: bash setup_elaina_ram.sh ELAINA_baru"
  exit 1
fi
if ! command -v base64 >/dev/null 2>&1; then
  echo "[ELAINA] Perintah base64 tidak ditemukan. Di Termux: pkg install coreutils"
  exit 1
fi
if ! command -v unzip >/dev/null 2>&1; then
  echo "[ELAINA] unzip belum terpasang. Di Termux: pkg install unzip"
  exit 1
fi
mkdir -p "$PROJECT_DIR"
TMP_ZIP="$PROJECT_DIR/.elaina_source.zip"
cleanup() { rm -f "$TMP_ZIP"; }
trap cleanup EXIT
base64 -d > "$TMP_ZIP" <<'ELAINA_RAM_ZIP_EOF'
